for(let i=0;i<90;i++){                                       // cacti across Coyote Canyon desert
 const a=Math.random()*Math.PI*2,rr=Math.random()*(CANYON.r*0.92);
 const x=CANYON.x+Math.cos(a)*rr, z=CANYON.z+Math.sin(a)*rr;
 if(Math.abs(z-riverZ(x))<7)continue;
 const col={x,z,r:0.6,plant:true};colliders.push(col);   // plant: course-clear may take it off a course before the model has even loaded
 (Math.random()<0.6?FOLIAGE.cactus:FOLIAGE.cactus2).push({x,z,s:0.9+Math.random()*1.0,r:Math.random()*Math.PI*2,col});
}
// Keep the settlement and its riding approaches open. Cull after generating
// placements so changing the planting does not consume a different random stream.
for(const name of ['cactus','cactus2'])for(let i=FOLIAGE[name].length-1;i>=0;i--){
 const p=FOLIAGE[name][i];if(pathDist(p.x,p.z)>=3.6&&Math.hypot(p.x-CANYON.x,p.z-CANYON.z)>=32&&!canyonPlacement.cliffAt(p.x,p.z))continue;
 const ci=colliders.indexOf(p.col);if(ci>=0)colliders.splice(ci,1);FOLIAGE[name].splice(i,1);
}
